window.LD=window.LD||{};window.LD["party/p5"]={"id":"p5","name":"The Green Arrows","poss":"The Green Arrows'","members":["h17","h13"],"leader":"h17","morale":97,"disposition":"friendly","motto":"Hugs after the fighting.","banner":{"c1":"#4caf50","c2":"#2f9e9e","emblem":"arrows"},"loc":"ironhaven","loc_name":"Ironhaven","goal":{"text":"to earn 300 silver between them before the season ends","kind":"purse","done":77,"progress":"1,860 silver, past the 300 aimed for","missed":false,"crew":"The Green Arrows","party":"p5"},"vows":[{"text":"to repay The Tidal Ledger","day":22,"state":"kept","ended":22,"through":false,"progress":"kept on day 22 of season 1","crew":"The Green Arrows","party":"p5"},{"text":"never to retreat","day":31,"state":"broken","ended":75,"through":false,"progress":"broken on day 15 of season 3","crew":"The Green Arrows","party":"p5"}],"doing":"last seen on the road to Thornwall","progress":null,"today":["Coin between them: -8 silver (inns 8)."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"gulls_took_lunch","title":"The Gulls Took My Lunch","tone":"funny","meter":"6/8","bpm":114,"diff":2,"day":20,"night":"n42","n":11,"by":null,"lead":{"id":"h17","name":"Fenwick","skill":0.61,"inst":"flute"}},"renown":216,"season":{"wins":6,"bosses":0,"floors":2,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":1},"career":{"wins":35,"bosses":3,"floors":16,"gold":0,"deaths":0,"fled":2,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":2},"former":[],"fallen":[],"travel":{"from":"ironhaven","to":"thornwall","left":1,"total":2,"dest":"thornwall","counted":true},"wagon":{"kind":"carriage","name":"Bumpy","label":"carriage","seats":5,"haul":10,"comfort":-3,"since":64,"desc":"Cushions, curtains and a door that shuts. Every bandit on the road notices.","moves":true,"puller":{"kind":"horse","name":"Captain","label":"riding horse","colour":"black","owner":null},"paid":[["Bramble",133],["Fenwick",22]]},"pace_gap":0,"rels":[{"party":"p2","score":100},{"party":"p7","score":100},{"party":"p1","score":37},{"party":"p4","score":24},{"party":"p6","score":14}],"events":[{"id":"e31","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Fenwick and Bramble shake on it at The Sagging Beam: they are now The Green Arrows. (Friendly, by the look of them.)","heroes":["h17","h13"],"parties":["p5"],"loc":"thornwall","wx":"fog"},{"id":"e165","day":5,"season":1,"sday":5,"kind":"boss","imp":5,"text":"Gruk the Warchief and a Goblin Shaman fall at last at the bottom of Goblin Camp, brought down by the Green Arrows. It couldn't see a thing after Bramble's Feint. Fenwick found the weak spot first and kept hitting it. Bramble kept the bleeding to a minimum. Loot: 23 silver each, 6 goblin ears, 5 trinkets.","heroes":["h17","h13"],"parties":["p5"],"loc":"goblin_camp","fight":"f15","foes":["goblin_warchief","goblin_shaman"],"where":"at the bottom of Goblin Camp","won":true,"close":false,"shape":"foe","reworded":-10,"wx":"fog"},{"id":"e169","day":5,"season":1,"sday":5,"kind":"gear","imp":4,"text":"Bramble comes out of Goblin Camp with a greasy belt hung with a dozen bent spoons from the warchief's hole. There is only one of those, and nobody yet knows what it does.","heroes":["h17","h13"],"parties":["p5"],"loc":"goblin_camp","wx":"fog"},{"id":"e206","day":5,"season":1,"sday":5,"kind":"big_move","imp":4,"text":"Gruk the Warchief and a Goblin Shaman fall at last at the bottom of Goblin Camp, brought down by the Green Arrows. On the table: The Green Arrows +90 party renown (2nd to 1st among the crews).","heroes":["h17","h13"],"parties":["p5"],"party_moves":[{"party":"p5","gain":90,"from":2,"to":1}],"cause":"e165","fight":"f15"},{"id":"e539","day":15,"season":1,"sday":15,"kind":"boss","imp":5,"text":"Seven rounds in, the Green Arrows bring down the Mimic King and a Kobold Slinger at the bottom of Cragtooth Warren. After Bramble's Disarm, the Mimic King hit like a tired farmhand. Bramble kept them off everyone with Inspire. Loot: 120 silver each, 2 gems, 12 trinkets.","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","fight":"f47","foes":["mimic_king","kobold_slinger"],"where":"at the bottom of Cragtooth Warren","won":true,"close":true,"shape":"close","reworded":-23},{"id":"e544","day":15,"season":1,"sday":15,"kind":"gear","imp":4,"text":"A ring that feels faintly damp from the hoard hall leaves the dark of Cragtooth Warren in Bramble's pack. There isn't another. What it can do is anyone's guess until a town names it.","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e574","day":15,"season":1,"sday":15,"kind":"goal_done","imp":4,"text":"GOAL: The Green Arrows set out to earn 200 silver between them before the season ends, and they have done it, with 15 days to spare. XP: Fenwick +800 (level 11!), Bramble +800 (level 11!).","heroes":["h17","h13"],"parties":["p5"],"xp":{"h17":800,"h13":800}},{"id":"e577","day":15,"season":1,"sday":15,"kind":"big_move","imp":4,"text":"Seven rounds in, the Green Arrows bring down the Mimic King and a Kobold Slinger at the bottom of Cragtooth Warren. On the table: Bramble +117 renown (2nd to 1st) and Fenwick +116 (holds 2nd). The Green Arrows +161 party renown (2nd to 1st among the crews).","heroes":["h13","h17"],"parties":["p5"],"cause":"e539","moves":[{"hero":"h13","gain":117,"from":2,"to":1},{"hero":"h17","gain":116,"from":1,"to":2}],"party_moves":[{"party":"p5","gain":161,"from":2,"to":1}],"fight":"f47"},{"id":"e764","day":20,"season":1,"sday":20,"kind":"talent","imp":2,"text":"Fenwick sorts trap parts on a blanket by size, then by age, then by how much he likes them. That's Professional Courtesy for you.","heroes":["h17"],"parties":["p5"],"loc":"ashveil_crypts","skill":"professional_courtesy"},{"id":"e766","day":20,"season":1,"sday":20,"kind":"meet","imp":2,"text":"The Tidal Ledger and The Green Arrows share a fire in the Ashveil Crypts and trade news.","heroes":["h7","h19","h2","h14","h17","h13"],"parties":["p7","p5"],"loc":"ashveil_crypts"},{"id":"e768","day":20,"season":1,"sday":20,"kind":"talent","imp":1,"text":"Bramble reads the claw marks on a wall like a menu. 'Big. Slow on the left side.' Fenwick takes notes. Somebody asks how. 'Bane of Bosses,' says Bramble.","heroes":["h13","h17"],"parties":["p5"],"loc":"ashveil_crypts","skill":"bane_of_bosses"},{"id":"e772","day":20,"season":1,"sday":20,"kind":"music","imp":3,"text":"Last night \"The Gulls Took My Lunch\" stopped being a song The Green Arrows sing and became The Green Arrows' song. Anyone who was there could tell the moment it happened.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","anthem":"gulls_took_lunch","night":"n42"},{"id":"e806","day":21,"season":1,"sday":21,"kind":"delve","imp":1,"text":"The Green Arrows descend into the Ashveil Crypts, mostly explored (77%).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e808","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"Two Risen Dead and a Skeleton fall to the Green Arrows in the coffin racks on floor 2 of the Ashveil Crypts. Bramble stepped in with Feint, and the skeleton was on the ground. Loot: 2 crypt-caps, 2 bones, 2 grave dust.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f68","foes":["zombie","skeleton","zombie"],"where":"in the coffin racks on floor 2 of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-2},{"id":"e809","day":21,"season":1,"sday":21,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Ashveil Crypts at a steady pace: 2 rooms (the bell chamber, the coffin racks).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]}},{"id":"e810","day":21,"season":1,"sday":21,"kind":"talent","imp":1,"text":"Bramble sharpens her weapon all evening, humming the name of the next floor's boss.","heroes":["h13"],"parties":["p5"],"loc":"ashveil_crypts","skill":"bane_of_bosses"},{"id":"e831","day":22,"season":1,"sday":22,"kind":"fight","imp":3,"text":"The Green Arrows are routed by Vessimir the Unburied and Risen Dead at the bottom of the Ashveil Crypts and run for it. Fenwick hasn't said a word since.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f70","foes":["necromancer","zombie"],"where":"at the bottom of The Ashveil Crypts","won":false,"close":true,"shape":"plain"},{"id":"e832","day":22,"season":1,"sday":22,"kind":"rescue","imp":4,"text":"RESCUE in the Ashveil Crypts: Vex (Chris's hero) finds Fenwick (Quinn's hero) bleeding in the dark and does not walk past. 2 potions later, Fenwick is breathing properly.","heroes":["h7","h17","h19","h2","h14","h13"],"parties":["p7","p5"],"loc":"ashveil_crypts","rescuers":["h7","h19","h2","h14"]},{"id":"e833","day":22,"season":1,"sday":22,"kind":"vow","imp":3,"text":"Patched up and humbled, The Green Arrows swear to repay The Tidal Ledger, one day, somehow.","heroes":["h17","h13"],"parties":["p5"],"cause":"e832"},{"id":"e834","day":22,"season":1,"sday":22,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Ashveil Crypts at a push pace: 2 rooms (the Lorne vault, the lowest crypt).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":2,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":2,"unwalked":1,"fights":1,"close":1,"gear":[],"fears":2,"wild":[]}},{"id":"e835","day":22,"season":1,"sday":22,"kind":"delve_done","imp":1,"text":"A fight goes the wrong way, and after 2 days below The Green Arrows come up the stairs at a pace nobody calls a retreat out loud. They reached the deepest floor and cleared 3 rooms.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","days":2,"bottom":true,"rooms":[],"gold":0,"out":"Driven out","turn":"routed"},{"id":"e841","day":22,"season":1,"sday":22,"kind":"vow_kept","imp":5,"text":"VOW KEPT. Debt paid: The Green Arrows pull The Tidal Ledger out of trouble, as sworn on day 22 of season 1.","heroes":["h17","h13"],"parties":["p5"],"cause":"e833"},{"id":"e842","day":22,"season":1,"sday":22,"kind":"rescue","imp":5,"text":"Bramble (Casey's hero) has been waiting since day 22 of season 1 to pay this one back. Vex (Chris's hero) is in trouble in the Ashveil Crypts; Bramble is there.","heroes":["h13","h7","h17","h19","h2","h14"],"parties":["p5","p7"],"loc":"ashveil_crypts","cause":"e832","rescuers":["h17","h13"]},{"id":"e892","day":23,"season":1,"sday":23,"kind":"party_life","imp":1,"text":"Bramble waits at every crossroads for Fenwick to catch up, and says nothing very loudly.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e893","day":23,"season":1,"sday":23,"kind":"road","imp":3,"text":"Tansy Fell has heard of rats in the hundreds near the Collapsed Mine, she tells Bramble, and means to do something about it for a decent fee.","heroes":["h13","h17"],"parties":["p5"],"road":"ashfen~ashveil_crypts","traveller":"tansy","road_rec":"r162"},{"id":"e918","day":23,"season":1,"sday":23,"kind":"journey","imp":2,"text":"The Green Arrows and The Tidal Ledger fall in together on the road to Ashfen and spend the miles arguing about Bramble's terrible singing.","heroes":["h17","h13","h7","h19","h2","h14"],"parties":["p5","p7"]},{"id":"e945","day":24,"season":1,"sday":24,"kind":"map_bought","imp":2,"text":"The Green Arrows buy a map of the Ashveil Crypts in Ashfen for 16 silver, drawn by Vex. The place is mostly explored (82%).","heroes":["h17","h13","h7"],"parties":["p5"],"loc":"ashfen"},{"id":"e979","day":25,"season":1,"sday":25,"kind":"delve","imp":1,"text":"The Green Arrows descend into the Ashveil Crypts, mostly explored (82%), map in hand.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e981","day":25,"season":1,"sday":25,"kind":"boss","imp":5,"text":"At the bottom of the Ashveil Crypts, it's over: the Green Arrows put an end to Vessimir the Unburied and a Skeleton Archer. Without Fenwick's Field Dressing, Bramble doesn't walk out of that one. Bramble saved Battle Cry for when it mattered. Loot: 158 silver each, 12 ectoplasm, 14 grave dust. (A street palmist in Ashfen said this would happen. Bramble is going to have to tip her.)","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f82","foes":["necromancer","skeleton_archer"],"cause":"e724","where":"at the bottom of The Ashveil Crypts","won":true,"close":true,"shape":"place","reworded":-21},{"id":"e982","day":25,"season":1,"sday":25,"kind":"treasure","imp":2,"text":"Under the bedding of Vessimir the Unburied, rank and lumpy, lies 11 gold pieces and 6 silver.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","in_fight":"f82"},{"id":"e983","day":25,"season":1,"sday":25,"kind":"gear","imp":4,"text":"Bramble comes out of the Ashveil Crypts with a pale mask with a calm, sleeping face from the lowest crypt. There is only one of those, and nobody yet knows what it does.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts"},{"id":"e984","day":25,"season":1,"sday":25,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Ashveil Crypts at a push pace: 1 room (the lowest crypt).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":1,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["unique"],"fears":0,"wild":[]}},{"id":"e985","day":25,"season":1,"sday":25,"kind":"delve_done","imp":1,"text":"The Green Arrows come out into the light after a day with the dark still in every seam. They worked through 1 room, got all the way to the bottom, found the lowest crypt and split 548 silver on the way up.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","days":1,"bottom":true,"rooms":["the lowest crypt"],"gold":548,"turn":"done"},{"id":"e1009","day":25,"season":1,"sday":25,"kind":"big_move","imp":4,"text":"At the bottom of the Ashveil Crypts, it's over: the Green Arrows put an end to Vessimir the Unburied and a Skeleton Archer. On the table: Bramble +146 renown (2nd to 1st) and Fenwick +122 (holds 2nd). The Green Arrows +188 party renown (holds 1st among the crews).","heroes":["h13","h17"],"parties":["p5"],"cause":"e981","moves":[{"hero":"h13","gain":146,"from":2,"to":1},{"hero":"h17","gain":122,"from":1,"to":2}],"party_moves":[{"party":"p5","gain":188,"from":1,"to":1}],"fight":"f82"},{"id":"e1013","day":26,"season":1,"sday":26,"kind":"night_game","imp":2,"text":"A voice from the ditch on the road to Ashfen says, I will not rob you if you beat me at Crooked Cards. The bandit climbs out, looking pleased with the terms. Fenwick loses at Crooked Cards, and the crew hands over 3 jars of ectoplasm while the bandit counts it twice. Bramble laughs all the way on the road to Ashfen and then asks Fenwick to tell it again.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashfen","night":"n57","monster_game":"bandit","wx":"rain"},{"id":"e1026","day":26,"season":1,"sday":26,"kind":"talent","imp":1,"text":"Bramble keeps a list of bosses on an Ashfen tavern wall. The landlord adds a second wall. Bane of Bosses, the guild calls it.","heroes":["h13"],"parties":["p5"],"loc":"ashfen","skill":"bane_of_bosses","wx":"rain"},{"id":"e1051","day":27,"season":1,"sday":27,"kind":"party_life","imp":1,"text":"Fenwick arrives at camp an hour behind Bramble and finds the good spot by the fire taken.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashfen"},{"id":"e1068","day":27,"season":1,"sday":27,"kind":"meet","imp":2,"text":"The Green Arrows warn The Scarlet Thorns about what's lurking in Bleakmarsh. The Scarlet Thorns pretend to already know.","heroes":["h17","h13","h6","h9"],"parties":["p5","p1"],"loc":"bleakmarsh"},{"id":"e1075","day":27,"season":1,"sday":27,"kind":"campfire","imp":1,"text":"Fenwick and Bramble race to the next milestone. Bramble wins, and Fenwick claims a technical foul.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e1114","day":28,"season":1,"sday":28,"kind":"ledger","imp":2,"text":"MARKET WEEK: 11 hauls sold across the realm, 631 silver all told. Biggest haul: Bramble, 116 silver in Ashfen. Back up from the deep: The Green Arrows (2 days in the Ashveil Crypts).","heroes":["h13","h17"],"parties":["p5"]},{"id":"e1127","day":29,"season":1,"sday":29,"kind":"fight","imp":2,"text":"The Green Arrows, in fine spirits lately, survive a Bog Crawler and a Swamp Troll in Bleakmarsh. The bog crawler took Bramble's Feint full on and was never the same after. Fenwick's Trip Wire turned the fight. Loot: 14 silver each, 2 chitin, 2 bog crawler claws.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f91","foes":["bog_crawler","swamp_troll"],"where":"in Bleakmarsh","won":true,"close":true,"shape":"mood","reworded":-25},{"id":"e1141","day":29,"season":1,"sday":29,"kind":"meet","imp":1,"text":"The Green Arrows and The Tidal Ledger share a fire in Bleakmarsh and trade news.","heroes":["h17","h13","h7","h19","h2","h14"],"parties":["p5","p7"],"loc":"bleakmarsh"},{"id":"e1143","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Fenwick walks the road with his eyes on the ground, picking up every bit of wire anyone ever dropped. Professional Courtesy: one of the things Fenwick learned the long way round.","heroes":["h17"],"parties":["p5"],"loc":"bleakmarsh","skill":"professional_courtesy"},{"id":"e1188","day":30,"season":1,"sday":30,"kind":"fight","imp":1,"text":"With Fenwick hitting hardest, the Green Arrows handle a Will-o'-Wisp in Bleakmarsh. After Fenwick's Trip Wire, the will-o'-wisp hit like a tired farmhand. Loot: 2 wisp sugar.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f95","foes":["wisp"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"hero","reworded":-30},{"id":"e1189","day":30,"season":1,"sday":30,"kind":"night","imp":2,"text":"A grey dwarf shares The Green Arrows' fire in Bleakmarsh and swears on his beard there's a room in the Wolf Den nobody has opened. There isn't much beard left.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e1214","day":30,"season":1,"sday":30,"kind":"season_end","imp":5,"text":"Season 1 ends. Bramble is Hero of the Season with 517 renown. The Green Arrows finish as the top party.","heroes":["h13","h17"],"parties":["p5"]},{"id":"e1215","day":30,"season":1,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: The Green Arrows (Fenwick and Bramble) end season 1 as the league's best crew, 679 party renown. Their season: 3 bosses, 12 fights won and 9 floors explored.","heroes":["h17","h13"],"parties":["p5"]},{"id":"e1240","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"The rivalry resumes: Sunlit Quills and The Green Arrows are both bound for Cragtooth Warren, and The Mimic King's Ghost only dies once.","heroes":["h11","h20","h17","h13"],"parties":["p2","p5"],"loc":"cragtooth_warren"},{"id":"e1243","day":31,"season":2,"sday":1,"kind":"talent","imp":1,"text":"Fenwick straightens a crooked inn sign near Thornwall with one arrow through the chain link. The innkeeper waves.","heroes":["h17"],"parties":["p5"],"loc":"thornwall","skill":"trick_shot"},{"id":"e1255","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"A month in The Green Arrows together. Fenwick and Bramble know each other's snores, sorrows and orders by heart.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornwall"},{"id":"e1256","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Fenwick and Bramble share the last pickled onion by cutting it exactly in half, with witnesses.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornwall"},{"id":"e1266","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from The Green Arrows: never to retreat. Easy to say on day one.","heroes":["h17","h13"],"parties":["p5"]},{"id":"e1301","day":33,"season":2,"sday":3,"kind":"party_life","imp":1,"text":"Fenwick asks Bramble if the view is nice up there. It is.","heroes":["h17","h13"],"parties":["p5"],"loc":"ironhaven"},{"id":"e1302","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Bramble turns the Torc of the Last Stand on her neck and thinks about bridges. The bridge held.","heroes":["h13"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e1321","day":33,"season":2,"sday":3,"kind":"talent","imp":1,"text":"Fenwick leaves a polite note on a disarmed trap: 'Nice spring. Wrong angle.'","heroes":["h17"],"parties":["p5"],"loc":"cragtooth_warren","skill":"professional_courtesy"},{"id":"e1340","day":34,"season":2,"sday":4,"kind":"delve","imp":1,"text":"The Green Arrows descend into Cragtooth Warren, untouched (0%).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e1341","day":34,"season":2,"sday":4,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Cragtooth Warren at a push pace: 3 rooms (the prospectors' bunkhouse, a sealed space off the prospectors' bunkhouse, the golden gate).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","pace":"push","stats":{"rooms":3,"size":2,"floor":1,"traps":1,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1359","day":34,"season":2,"sday":4,"kind":"meet","imp":1,"text":"The Green Arrows and Sunlit Quills share a fire in Cragtooth Warren and trade news.","heroes":["h17","h13","h11","h20"],"parties":["p5","p2"],"loc":"cragtooth_warren"},{"id":"e1391","day":35,"season":2,"sday":5,"kind":"fight","imp":2,"text":"In the bat roost on floor 1 of Cragtooth Warren, the Green Arrows defeat 3 Giant Bats and a Kobold. Bramble's Disarm knocked half the fight out of the giant bat. Loot: 3 silver each, 4 fangs & claws, 2 bat wings.","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","fight":"f107","foes":["giant_bat","kobold","giant_bat"],"where":"in the bat roost on floor 1 of Cragtooth Warren","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e1392","day":35,"season":2,"sday":5,"kind":"fight","imp":1,"text":"The Green Arrows see off 2 Kobold Slingers and a Kobold in the slingers' gallery on floor 1 of Cragtooth Warren. Fenwick's Trip Wire took the strength out of the kobold. Loot: 11 silver each, 7 kobold firepeppers.","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","fight":"f108","foes":["kobold","kobold_slinger","kobold_slinger"],"where":"in the slingers' gallery on floor 1 of Cragtooth Warren","won":true,"close":false,"shape":"plain"},{"id":"e1393","day":35,"season":2,"sday":5,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Cragtooth Warren at a steady pace: 3 rooms (the bat roost, the kobold crawl, the slingers' gallery).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e1415","day":35,"season":2,"sday":5,"kind":"campfire","imp":1,"text":"Fenwick carves Bramble's initials into the campfire log. Bramble carves a rude drawing next to them. Friendship.","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e1428","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Cragtooth Warren at a cautious pace: 2 rooms (the claim board, a hidden room behind the claim board).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","pace":"cautious","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1445","day":36,"season":2,"sday":6,"kind":"argument","imp":2,"text":"Fenwick and Bramble spend supper disagreeing about the party's name, politely at first.","heroes":["h17","h13"],"parties":["p5"]},{"id":"e1464","day":37,"season":2,"sday":7,"kind":"fight","imp":1,"text":"Win number six in a row: the Green Arrows beat a Kobold Slinger, a Goblin Archer and a Kobold in the chief's hall on floor 1 of Cragtooth Warren. Feint, from Bramble, was the last thing the goblin archer saw. Loot: 8 silver each, 2 ore, 1 goblin ear.","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","fight":"f114","foes":["kobold_slinger","goblin_archer","kobold"],"where":"in the chief's hall on floor 1 of Cragtooth Warren","won":true,"close":false,"shape":"streak","reworded":-25,"wx":"rain"},{"id":"e1465","day":37,"season":2,"sday":7,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Cragtooth Warren at a steady pace: 2 rooms (the sleeping burrows, the chief's hall).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1489","day":38,"season":2,"sday":8,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Cragtooth Warren at a steady pace: 3 rooms (a rope ladder knotted by someone with very small hands, the bone midden, the kobold crawl).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1490","day":38,"season":2,"sday":8,"kind":"ambush","imp":3,"text":"A Giant Bat and a Kobold Slinger come at the Green Arrows' camp on floor 1 of Cragtooth Warren in the middle of the night, and the Green Arrows defeat them. Bramble's Battle Cry came at the right time for all of them. Without Fenwick's Trip Wire, this goes differently. Loot: 5 silver each, 4 kobold firepeppers.","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","fight":"f118","foes":["giant_bat","kobold_slinger"],"where":"at their camp on floor 1 of Cragtooth Warren, in the middle of the night","won":true,"close":false,"shape":"night","reworded":-26},{"id":"e1522","day":39,"season":2,"sday":9,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of Cragtooth Warren at a steady pace: 2 rooms (the black cistern, the coin-floored room).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":2,"size":2,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1530","day":39,"season":2,"sday":9,"kind":"talent","imp":1,"text":"Bramble stands at the boss's door, cracks her knuckles and knocks politely.","heroes":["h13"],"parties":["p5"],"loc":"cragtooth_warren","skill":"bane_of_bosses"},{"id":"e1557","day":40,"season":2,"sday":10,"kind":"gear","imp":1,"text":"In a walled-up room beside the mushroom terraces on floor 2 of Cragtooth Warren, Bramble finds a Sturdy Garnet Ring and puts it on. Sturdy: a little better protected (+1.5 armour).","heroes":["h13"],"parties":["p5"],"loc":"cragtooth_warren","wx":"heat"},{"id":"e1558","day":40,"season":2,"sday":10,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of Cragtooth Warren at a push pace: 2 rooms (a walled-up room beside the mushroom terraces, the chest graveyard).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","pace":"push","stats":{"rooms":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":0,"wild":[]},"wx":"heat"},{"id":"e1559","day":40,"season":2,"sday":10,"kind":"delve_done","imp":3,"text":"The Green Arrows climb the last ladder after 7 days, and the sitting down happens at the top of it. They went as deep as the place goes, turned up a sealed space off the prospectors' bunkhouse, a hidden room behind the claim board and a walled-up room beside the mushroom terraces, inked 67% of the map, worked through 17 rooms, came away with 166 silver between them and turned back because they were down to the last torch. All the crews' maps laid side by side say Cragtooth Warren is mostly explored (65%).","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","days":7,"bottom":true,"rooms":["a sealed space off the prospectors' bunkhouse","a hidden room behind the claim board"],"gold":166,"turn":"dark","wx":"heat"},{"id":"e1569","day":40,"season":2,"sday":10,"kind":"talent","imp":2,"text":"Bramble practises footwork by the fire, blade flashing. Fenwick watches and quietly copies the stance.","heroes":["h13","h17"],"parties":["p5"],"loc":"cragtooth_warren","skill":"sword_dancer","wx":"heat"},{"id":"e1604","day":41,"season":2,"sday":11,"kind":"party_life","imp":1,"text":"By the third crossroads Bramble has stopped waiting and started complaining about the wait.","heroes":["h17","h13"],"parties":["p5"],"loc":"cragtooth_warren","wx":"heat"},{"id":"e1621","day":41,"season":2,"sday":11,"kind":"journey","imp":2,"text":"On the way to Ironhaven, Sunlit Quills catch up with The Green Arrows. The conversation turns to what they'd do if they retired and never recovers.","heroes":["h11","h20","h17","h13"],"parties":["p2","p5"]},{"id":"e1622","day":41,"season":2,"sday":11,"kind":"talent","imp":1,"text":"Fenwick borrows a forge in Ironhaven for an hour, fixes the smith's gate as rent, then sharpens everything the crew owns. Fenwick puts it down to Smith's Hands.","heroes":["h17"],"parties":["p5"],"loc":"ironhaven","skill":"smith_hands","wx":"heat"},{"id":"e1640","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"The Green Arrows set their sights for the season: to finish the season as one of the top three parties.","heroes":["h17","h13"],"parties":["p5"]},{"id":"e1686","day":43,"season":2,"sday":13,"kind":"ambush","imp":2,"text":"A Bandit and a Bandit Captain fall to the Green Arrows on the road to Ashfen. The bandit captain couldn't see a thing after Bramble's Feint. Bramble's Second Intention turned the fight. When the line wavered, Bramble did not. The Torc of the Last Stand saw to that. \"Moving on,\" says Bramble. Loot: 41 silver each, 5 bandit sausages, 6 stolen goods.","heroes":["h17","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f128","foes":["bandit","bandit_captain"],"where":"on the road to Ashfen","won":true,"close":false,"shape":"foe","reworded":11,"wx":"heat"},{"id":"e1687","day":43,"season":2,"sday":13,"kind":"ambush","imp":2,"text":"The Green Arrows, in fine spirits lately, cut down a Bandit Captain and a Wolf at their camp on the road to Ashfen, in the middle of the night. The wolf took Bramble's Disarm full on and was never the same after. Fenwick's Trip Wire turned the fight. Loot: 49 silver each, 8 stolen goods, 1 fang.","heroes":["h17","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f129","foes":["bandit_captain","wolf"],"where":"at their camp on the road to Ashfen, in the middle of the night","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"heat"},{"id":"e1688","day":43,"season":2,"sday":13,"kind":"boss_race","imp":3,"text":"The rivalry resumes: Sunlit Quills and The Green Arrows are both bound for the Ashveil Crypts, and Vessimir the Unburied's Avenger only dies once.","heroes":["h11","h20","h17","h13"],"parties":["p2","p5"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1732","day":44,"season":2,"sday":14,"kind":"campfire","imp":1,"text":"Bramble grumbles about Fenwick's cooking all through supper and has seconds.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashfen","wx":"storm"},{"id":"e1752","day":45,"season":2,"sday":15,"kind":"road","imp":3,"text":"Granfer Oake shows Fenwick a dry cave he calls the Pantry. It is cold, with a good fire pit, and Fenwick sleeps better than in many an inn.","heroes":["h17","h13"],"parties":["p5"],"road":"ashfen~ashveil_crypts","traveller":"oake","road_rec":"r289"},{"id":"e1769","day":45,"season":2,"sday":15,"kind":"meet","imp":2,"text":"Sunlit Quills and The Green Arrows share a fire in the Ashveil Crypts and trade news.","heroes":["h11","h20","h17","h13"],"parties":["p2","p5"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1800","day":46,"season":2,"sday":16,"kind":"delve","imp":1,"text":"The Green Arrows descend into the Ashveil Crypts, mostly unexplored (10%).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1801","day":46,"season":2,"sday":16,"kind":"fight","imp":1,"text":"The Green Arrows make short work of 2 Skeletons in the gatehouse on floor 1 of the Ashveil Crypts. After Fenwick's Trip Wire, the skeleton hit like a tired farmhand. Loot: 11 bones.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f134","foes":["skeleton","skeleton"],"where":"in the gatehouse on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"plain","wx":"storm"},{"id":"e1802","day":46,"season":2,"sday":16,"kind":"gear","imp":1,"text":"In the gatehouse on floor 1 of the Ashveil Crypts, Fenwick finds a Grave-Blessed Brass Ring and puts it on. Grave-Blessed: much braver (+7 nerve).","heroes":["h17"],"parties":["p5"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1803","day":46,"season":2,"sday":16,"kind":"fight","imp":1,"text":"In the skeletons' quiet corner on floor 1 of the Ashveil Crypts, the Green Arrows square up to 2 Skeletons and carry the day. Bramble ended it the plain way: Feint, and the skeleton on the ground. Loot: 8 bones.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f135","foes":["skeleton","skeleton"],"where":"in the skeletons' quiet corner on floor 1 of the Ashveil Crypts","won":true,"close":false,"shape":"place","reworded":-25,"wx":"storm"},{"id":"e1804","day":46,"season":2,"sday":16,"kind":"wild_room","imp":3,"text":"Bramble, who is frightened of statues, outstared a chapel full of them. 'They blinked first,' Bramble said.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","room":"wild_musical_statues","wx":"storm"},{"id":"e1805","day":46,"season":2,"sday":16,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of the Ashveil Crypts at a push pace: 3 rooms (the gatehouse, the skeletons' quiet corner, the mourners' gallery).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["great"],"fears":2,"wild":["wild_musical_statues"]},"wx":"storm"},{"id":"e1806","day":46,"season":2,"sday":16,"kind":"ambush","imp":2,"text":"With Bramble hitting hardest, the Green Arrows beat a Giant Rat and a Skeleton at their camp on floor 1 of the Ashveil Crypts, in the middle of the night. Bramble landed Disarm on the skeleton hard enough to hear from the back. Bramble saved Battle Cry for when it mattered. Fenwick shouted at the bodies for a while afterwards. \"High five! No? Okay!\" says Fenwick. Loot: 4 bones, 2 trinkets, 2 crypt-caps.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f136","foes":["giant_rat","skeleton"],"where":"at their camp on floor 1 of The Ashveil Crypts, in the middle of the night","won":true,"close":false,"shape":"hero","reworded":-30,"wx":"storm"},{"id":"e1830","day":46,"season":2,"sday":16,"kind":"campfire","imp":1,"text":"Fenwick and Bramble get lost taking a short cut and blame the map, the sun and the local sheep.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1840","day":47,"season":2,"sday":17,"kind":"trap","imp":2,"text":"Bramble springs a coffin lid that falls in a stair of black slate with a name cut on every tread on floor 1 of the Ashveil Crypts (bruised ribs).","heroes":["h13"],"parties":["p5"],"loc":"ashveil_crypts","wx":"storm"},{"id":"e1841","day":47,"season":2,"sday":17,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of the Ashveil Crypts at a steady pace: 2 rooms (the sexton's lodging, a stair of black slate with a name cut on every tread).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":1,"sprung":1,"trap_inj":1,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"storm"},{"id":"e1873","day":48,"season":2,"sday":18,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of the Ashveil Crypts at a push pace: 3 rooms (the reliquary passage, the chantry, the grave-goods store).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":3,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":4,"wild":[]},"wx":"fog"},{"id":"e1913","day":49,"season":2,"sday":19,"kind":"fight","imp":2,"text":"Two Risen Dead and a Skeleton Archer stir in the bier hall on floor 2 of the Ashveil Crypts, and the Green Arrows defeat them for good. The risen dead had been trouble right up until Bramble's Feint. Loot: 6 crypt-caps, 2 bones.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f140","foes":["zombie","zombie","skeleton_archer"],"where":"in the bier hall on floor 2 of the Ashveil Crypts","won":true,"close":false,"shape":"foe","reworded":-26,"wx":"fog"},{"id":"e1914","day":49,"season":2,"sday":19,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Ashveil Crypts at a steady pace: 2 rooms (the bier hall, the grave-goods store).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1938","day":50,"season":2,"sday":20,"kind":"gear","imp":1,"text":"In a hidden room behind the Harrow vault on floor 2 of the Ashveil Crypts, Fenwick finds a Keen Delver's Strap and puts it on. Keen: a steadier aim (+2 aim).","heroes":["h17"],"parties":["p5"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e1939","day":50,"season":2,"sday":20,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of the Ashveil Crypts at a cautious pace: 2 rooms (the Harrow vault, a hidden room behind the Harrow vault).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"cautious","stats":{"rooms":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e1977","day":51,"season":2,"sday":21,"kind":"fight","imp":2,"text":"The Green Arrows, in fine spirits lately, cut down a Skeleton, Risen Dead and a Skeleton Archer in the long gallery on floor 3 of the Ashveil Crypts. The risen dead took Bramble's Feint full on and was never the same after. Loot: 5 bones, 5 crypt-caps.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f148","foes":["skeleton","zombie","skeleton_archer"],"where":"in the long gallery on floor 3 of the Ashveil Crypts","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"fog"},{"id":"e1978","day":51,"season":2,"sday":21,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Ashveil Crypts at a push pace: 3 rooms (the family archive, the Veyne vault, the long gallery).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"push","stats":{"rooms":3,"size":2,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2015","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"It takes the Green Arrows 9 rounds to outlast 2 Bone Constructs, a Skeleton Archer and Risen Dead in the crossing of galleries on floor 3 of the Ashveil Crypts. Bramble's Feint left the bone construct swinging at nothing. Without Fenwick's Trip Wire, this goes differently. Loot: 38 bones, 4 grave dust, 2 remains.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","fight":"f152","foes":["skeleton_archer","zombie","bone_construct"],"where":"in the crossing of galleries on floor 3 of the Ashveil Crypts","won":true,"close":true,"shape":"close","reworded":-21,"wx":"fog"},{"id":"e2016","day":52,"season":2,"sday":22,"kind":"gear","imp":1,"text":"In the crossing of galleries on floor 3 of the Ashveil Crypts, Bramble finds a pair of Grip Gloves of the Long Night and puts them on. Of the Long Night: much braver (+5 nerve).","heroes":["h13"],"parties":["p5"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2017","day":52,"season":2,"sday":22,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 3 of the Ashveil Crypts at a steady pace: 3 rooms (the crossing of galleries, the grave-goods heap, the sentinel niches).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","pace":"steady","stats":{"rooms":3,"size":2,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great","common"],"fears":2,"wild":[]},"wx":"fog"},{"id":"e2050","day":53,"season":2,"sday":23,"kind":"delve_done","imp":3,"text":"After 8 days underground, The Green Arrows climb back into the open air, gulping it down like water. They found the gatehouse, the mourners' gallery, the chantry and 5 more good rooms, got all the way to the bottom, put 49% of it on paper, took 18 rooms off the map's blank side, took the teeth out of 2 traps, came away with 151 silver between them and turned back because their nerves were fraying. The guild's map has it: The Ashveil Crypts is partly explored (62%).","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","days":8,"bottom":true,"rooms":["the gatehouse","the mourners' gallery"],"gold":151,"turn":"nerve","wx":"fog"},{"id":"e2072","day":53,"season":2,"sday":23,"kind":"campfire","imp":1,"text":"Fenwick brings back a brace of rabbits for the pot. Bramble cooks them. Teamwork.","heroes":["h17","h13"],"parties":["p5"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e2091","day":54,"season":2,"sday":24,"kind":"talent","imp":2,"text":"Fenwick trims a candle wick at the Ashfen tavern from across the room. The candle stays lit. The bets don't. Trick Shot, the way the old trappers taught it.","heroes":["h17"],"parties":["p5"],"loc":"ashfen","skill":"trick_shot"},{"id":"e2094","day":54,"season":2,"sday":24,"kind":"journey","imp":2,"text":"The Green Arrows and Sunlit Quills share the road to Ashfen. By the second milestone they've agreed on nothing, least of all old scars.","heroes":["h17","h13","h11","h20"],"parties":["p5","p2"]},{"id":"e2116","day":55,"season":2,"sday":25,"kind":"ambush","imp":2,"text":"Bramble takes the worst of it as the Green Arrows see off 3 Wolves on the road to Carrbridge. The last wolf doesn't stay to see the end. Fenwick's Trip Wire took the strength out of the wolf. Bramble's Second Intention kicked in when it counted. Loot: 2 pelts, 4 fangs & claws, a wolf haunch.","heroes":["h17","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f160","foes":["wolf","wolf","wolf"],"where":"on the road to Carrbridge","won":true,"close":false,"shape":"hero","reworded":-55},{"id":"e2117","day":55,"season":2,"sday":25,"kind":"road","imp":3,"text":"A full-rigged ship stands on a hill beside the road to Carrbridge, among grazing sheep, with her sails furled. Bramble asks a shepherd how and gets a shrug.","heroes":["h13","h17"],"parties":["p5"],"road":"ashfen~carrbridge","road_rec":"r356"},{"id":"e2151","day":56,"season":2,"sday":26,"kind":"bounty","imp":2,"text":"The Green Arrows cash in a season's worth of trophies at the Carrbridge guild: about 61 silver a head.","heroes":["h17"],"parties":["p5"],"loc":"carrbridge","amount":61},{"id":"e2203","day":58,"season":2,"sday":28,"kind":"fight","imp":2,"text":"In Bleakmarsh, the Green Arrows beat 2 Risen Dead and a Will-o'-Wisp. Bramble stepped in with Disarm, and the risen dead was on the ground. Loot: 2 wisp sugar, 6 grave dust, 2 crypt-caps.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f168","foes":["wisp","zombie","zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-1},{"id":"e2206","day":58,"season":2,"sday":28,"kind":"fight","imp":2,"text":"The Green Arrows handle 3 Bog Crawlers in Bleakmarsh without much fuss. The last bog crawler decides enough is enough, and goes. Bramble's Feint took most of the fight out of the bog crawler in one go. Loot: 9 chitin, 5 bog crawler claws.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f169","foes":["bog_crawler","bog_crawler","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"plain","reworded":-47},{"id":"e2212","day":58,"season":2,"sday":28,"kind":"meet","imp":2,"text":"The Green Arrows and The Scarlet Thorns share a fire in Bleakmarsh. Fenwick shares directions.","heroes":["h17","h13","h6","h9"],"parties":["p5","p1"],"loc":"bleakmarsh"},{"id":"e2221","day":58,"season":2,"sday":28,"kind":"campfire","imp":1,"text":"Fenwick replays the last fight for Bramble blow by blow. In this version, both are heroes. Both were.","heroes":["h13","h17"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e2242","day":59,"season":2,"sday":29,"kind":"fight","imp":2,"text":"In Bleakmarsh again, for the third time in two days: the Green Arrows cut down 2 Risen Dead. Bramble's Dashing Strike caught the risen dead square. It stayed down. Fenwick kept them off everyone with Snare Field.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f172","foes":["zombie","zombie"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"again","reworded":-39,"wx":"fog"},{"id":"e2247","day":59,"season":2,"sday":29,"kind":"talent","imp":2,"text":"Bramble pours a capful of homebrew for Fenwick at a rest stop. Fenwick coughs, then holds the cup out again.","heroes":["h13","h17"],"parties":["p5"],"loc":"bleakmarsh","skill":"brewer","wx":"fog"},{"id":"e2281","day":60,"season":2,"sday":30,"kind":"fight","imp":2,"text":"The Green Arrows make short work of 3 Bog Crawlers in Bleakmarsh, in thick fog. The last bog crawler turns tail. The bog crawler lost a turn to Fenwick's Snare Field. Second Intention did more for this fight than the scoreboard shows. That was Bramble. Loot: 2 chitin.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh","fight":"f175","foes":["bog_crawler","bog_crawler","bog_crawler"],"where":"in Bleakmarsh","won":true,"close":false,"shape":"weather","reworded":-19,"wx":"fog"},{"id":"e2290","day":60,"season":2,"sday":30,"kind":"campfire","imp":2,"text":"Bramble hangs Fenwick's wet socks by the fire with the care of someone hanging a tapestry.","heroes":["h13","h17"],"parties":["p5"],"loc":"bleakmarsh","wx":"fog"},{"id":"e2300","day":60,"season":2,"sday":30,"kind":"goal_missed","imp":3,"text":"Not this time: The Green Arrows' goal (finish the season as one of the top three parties) falls short (finished 4th).","heroes":["h17","h13"],"parties":["p5"]},{"id":"e2331","day":61,"season":3,"sday":1,"kind":"party_life","imp":1,"text":"Bramble rides ahead, rides back, rides ahead again. Fenwick is not amused.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornwall"},{"id":"e2332","day":61,"season":3,"sday":1,"kind":"road","imp":3,"text":"Marigold sets up the pot for supper. Fenwick is given the spoon to hold, and the smell makes the miles ahead seem short.","heroes":["h17","h13"],"parties":["p5"],"road":"hollowood~thornwall","traveller":"marigold","road_rec":"r402"},{"id":"e2393","day":63,"season":3,"sday":3,"kind":"party_life","imp":1,"text":"Fenwick arrives at camp an hour behind Bramble and finds the good spot by the fire taken.","heroes":["h17","h13"],"parties":["p5"],"loc":"hollowood"},{"id":"e2395","day":63,"season":3,"sday":3,"kind":"road","imp":3,"text":"Bramble is surprised to find a ridge on Ines's map marked with her own name. She has been drawing it all week.","heroes":["h13","h17"],"parties":["p5"],"road":"hollowood~thornwall","traveller":"ines","road_rec":"r417"},{"id":"e2411","day":63,"season":3,"sday":3,"kind":"boss_race","imp":3,"text":"The rivalry resumes: Sunlit Quills and The Green Arrows are both bound for Thornmere Ruins, and Mother Thornmere's Brood only dies once.","heroes":["h11","h20","h17","h13"],"parties":["p2","p5"],"loc":"thornmere_ruins"},{"id":"e2424","day":64,"season":3,"sday":4,"kind":"wagon","imp":3,"text":"The Green Arrows roll out of Thornwall in a carriage called Bumpy, 155 silver between them. Who paid: Bramble 133, Fenwick 22.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornwall"},{"id":"e2439","day":64,"season":3,"sday":4,"kind":"talent","imp":2,"text":"A Thornwall clockmaker takes a box of Fenwick's spare trap springs off his hands for a fair price and asks no questions. (Professional Courtesy, if anyone's asking.)","heroes":["h17"],"parties":["p5"],"loc":"thornwall","skill":"professional_courtesy"},{"id":"e2460","day":65,"season":3,"sday":5,"kind":"ambush","imp":2,"text":"The Bounty Hunters' Captain and Bounty Hunter fall to the Green Arrows on the road out of Thornwall, sent for the price on Bramble's head. Bramble found the bounty hunter with Feint and nearly split it in two. Fenwick's Snare Field turned the fight. Loot: 42 silver each, 7 stolen goods, 1 gem.","heroes":["h17","h13"],"parties":["p5"],"loc":"kingsroad","fight":"f193","foes":["bandit_captain","bandit"],"where":"on the road out of Thornwall, sent for the price on Bramble's head","won":true,"close":false,"shape":"foe","reworded":1},{"id":"e2468","day":65,"season":3,"sday":5,"kind":"talent","imp":1,"text":"Fenwick sets a Carrbridge roofer's wrist and splints it with two spoons. The roofer's family insists on paying. A small Bone Setting, cast without looking up.","heroes":["h17"],"parties":["p5"],"loc":"carrbridge","skill":"bone_setting"},{"id":"e2472","day":65,"season":3,"sday":5,"kind":"campfire","imp":1,"text":"After the fight, Bramble and Fenwick sit back to back on a rock and don't say anything for a long time.","heroes":["h13","h17"],"parties":["p5"],"loc":"carrbridge"},{"id":"e2509","day":66,"season":3,"sday":6,"kind":"talent","imp":1,"text":"Bramble checks the little keg strapped to the mule. It's coming along. It smells like a decision.","heroes":["h13"],"parties":["p5"],"loc":"bleakmarsh","skill":"brewer"},{"id":"e2521","day":67,"season":3,"sday":7,"kind":"party_life","imp":1,"text":"Fenwick pays the stable boy for the Bumpy and counts the change twice, out loud.","heroes":["h17"],"parties":["p5"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2536","day":67,"season":3,"sday":7,"kind":"meet","imp":2,"text":"The Green Arrows and Sunlit Quills pass on the road between Bleakmarsh and Thornmere Ruins. There is a short argument about the best road to Carrbridge.","heroes":["h17","h13","h11","h20"],"parties":["p5","p2"],"loc":"bleakmarsh","wx":"rain"},{"id":"e2544","day":67,"season":3,"sday":7,"kind":"talent","imp":2,"text":"Fenwick copies out the party charter in gold-ish ink. Bramble insists on signing it with a flourish.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"calligrapher","wx":"rain"},{"id":"e2551","day":68,"season":3,"sday":8,"kind":"delve","imp":1,"text":"The Green Arrows descend into Thornmere Ruins, mostly unexplored (11%).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e2552","day":68,"season":3,"sday":8,"kind":"fight","imp":1,"text":"The Green Arrows, in fine spirits lately, defeat 2 Will-o'-Wisps and a Siren in the choir loft on floor 1 of Thornmere Ruins. Bramble's Dashing Strike took most of the fight out of the will-o'-wisp in one go. Loot: 6 trinkets, 5 bottled wisplight, 5 wisp sugar.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f198","foes":["siren","wisp","wisp"],"where":"in the choir loft on floor 1 of Thornmere Ruins","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"rain"},{"id":"e2553","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the scriptorium, the choir loft).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"rain"},{"id":"e2554","day":68,"season":3,"sday":8,"kind":"talent","imp":1,"text":"Fenwick knocks a pine cone off a branch in the dark, by sound alone. Bramble demands to see it again. Trick Shot: a ranger's patience, mostly.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"trick_shot","wx":"rain"},{"id":"e2588","day":69,"season":3,"sday":9,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a push pace: 3 rooms (the porters' lodge, the priests' cells, a walled-up room beside the priests' cells).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":3,"size":2,"floor":1,"traps":0,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2614","day":70,"season":3,"sday":10,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a push pace: 2 rooms (the wayside cross, the sunken stair).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2655","day":71,"season":3,"sday":11,"kind":"gear","imp":1,"text":"In a walled-up room beside the sunken stair on floor 1 of Thornmere Ruins, Fenwick finds a Quick Kite Shield, and stashes it to sell. Quicker (+0.8 speed).","heroes":["h17"],"parties":["p5"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e2656","day":71,"season":3,"sday":11,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the pilgrims' hall, a walled-up room beside the sunken stair).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2658","day":71,"season":3,"sday":11,"kind":"talent","imp":2,"text":"Fenwick sets Bramble's dislocated finger with one tug and a joke to distract. Clean and quick. A small Bone Setting, cast without looking up.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"bone_setting","wx":"fog"},{"id":"e2673","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"The Green Arrows set their sights for the season: to earn 300 silver between them before the season ends.","heroes":["h17","h13"],"parties":["p5"]},{"id":"e2687","day":72,"season":3,"sday":12,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a cautious pace: 2 rooms (the temple fish ponds, a sealed space off the temple fish ponds).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":0,"wild":[]},"wx":"fog"},{"id":"e2712","day":73,"season":3,"sday":13,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the sunken stair behind the font, the chandlery).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e2734","day":73,"season":3,"sday":13,"kind":"talent","imp":1,"text":"Fenwick beats a dent out of Bramble's helmet on a flat rock. It fits better than it did new. Smith's Hands, the guild calls it.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","skill":"smith_hands","wx":"rain"},{"id":"e2754","day":74,"season":3,"sday":14,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 1 of Thornmere Ruins at a steady pace: 2 rooms (the sacristy, the reed-choked treasury).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e2785","day":75,"season":3,"sday":15,"kind":"fight","imp":3,"text":"In the drowned nave on floor 2 of Thornmere Ruins, the Green Arrows are routed by 3 Swamp Trolls. Bramble covered the retreat. \"Later,\" says Bramble. Injured: Bramble (sprained ankle).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","fight":"f215","foes":["swamp_troll","swamp_troll","swamp_troll"],"where":"in the drowned nave on floor 2 of Thornmere Ruins","won":false,"close":true,"shape":"place","reworded":14,"wx":"rain"},{"id":"e2786","day":75,"season":3,"sday":15,"kind":"vow_broken","imp":4,"text":"So much for never to retreat: The Green Arrows ran from a fight. The vow lasted 44 days.","heroes":["h17","h13"],"parties":["p5"],"cause":"e1266"},{"id":"e2787","day":75,"season":3,"sday":15,"kind":"delve_day","imp":1,"text":"The Green Arrows work floor 2 of Thornmere Ruins at a steady pace: 2 rooms (the illuminators' desks, the drowned nave).","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":2,"size":2,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":1,"gear":[],"fears":1,"wild":[]},"wx":"rain"},{"id":"e2788","day":75,"season":3,"sday":15,"kind":"delve_done","imp":3,"text":"After 8 days and one bad fight, The Green Arrows climb out, calling it a retreat with dignity. They put 30% of it on paper, made it to floor 2, found a walled-up room beside the priests' cells, a walled-up room beside the sunken stair, a sealed space off the temple fish ponds and 3 more good rooms, cleared 16 rooms and split 319 silver on the way up. Thornmere Ruins is mostly unexplored (31%) now, with the league's pencil marks all over it.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","days":8,"bottom":false,"rooms":["a walled-up room beside the priests' cells","a walled-up room beside the sunken stair"],"gold":319,"out":"Driven out","turn":"routed","wx":"rain"},{"id":"e2789","day":75,"season":3,"sday":15,"kind":"night","imp":2,"text":"Bramble follows strange lights away from the camp outside Thornmere Ruins, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e2816","day":75,"season":3,"sday":15,"kind":"goal_progress","imp":2,"text":"The Green Arrows are getting close: earn 300 silver between them before the season ends (184 of 300 silver).","heroes":["h17","h13"],"parties":["p5"]},{"id":"e2837","day":76,"season":3,"sday":16,"kind":"gift","imp":2,"text":"Bramble admired Fenwick's Compass That Points to Ironhaven one too many times. Now it's Bramble's.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e2838","day":76,"season":3,"sday":16,"kind":"talent","imp":2,"text":"Fenwick spots feverfew in a ditch near Bleakmarsh and bags it before anyone else notices. Every snaremaster learns Forager sooner or later. Not every snaremaster learns it like that.","heroes":["h17"],"parties":["p5"],"loc":"bleakmarsh","skill":"forager"},{"id":"e2846","day":76,"season":3,"sday":16,"kind":"argument","imp":1,"text":"Bramble and Fenwick of The Green Arrows have a shouting match about whose idea the last dungeon was.","heroes":["h13","h17"],"parties":["p5"]},{"id":"e2847","day":76,"season":3,"sday":16,"kind":"campfire","imp":1,"text":"Fenwick and Bramble share a rain cloak in a downpour and arrive soaked and laughing.","heroes":["h17","h13"],"parties":["p5"],"loc":"bleakmarsh"},{"id":"e2877","day":77,"season":3,"sday":17,"kind":"campfire","imp":3,"text":"Bramble patches Fenwick's cloak without being asked. Fenwick pretends not to notice, then says thanks.","heroes":["h17","h13"],"parties":["p5"],"loc":"carrbridge","wx":"storm"},{"id":"e2885","day":77,"season":3,"sday":17,"kind":"goal_done","imp":4,"text":"GOAL: The Green Arrows set out to earn 300 silver between them before the season ends, and they have done it, with 13 days to spare. XP: Fenwick +960, Bramble +800.","heroes":["h17","h13"],"parties":["p5"],"xp":{"h17":960,"h13":800}},{"id":"e2894","day":78,"season":3,"sday":18,"kind":"road","imp":2,"text":"Bramble falls in beside Teodor for the first time, who tunes the lute while walking and says the road is 'in the key of mud'.","heroes":["h13","h17"],"parties":["p5"],"road":"carrbridge~thornwall","traveller":"teodor","road_rec":"r529"},{"id":"e2910","day":78,"season":3,"sday":18,"kind":"campfire","imp":1,"text":"Fenwick walks the dark side of the road so Bramble doesn't have to, and never says why.","heroes":["h17","h13"],"parties":["p5"],"loc":"thornwall"},{"id":"e2985","day":80,"season":3,"sday":20,"kind":"road","imp":4,"text":"Bramble walks into a town to hear Teodor singing 'The Walking Song of Bramble' in a tavern. It has all its verses, and the last one is kind.","heroes":["h13","h17"],"parties":["p5"],"road":"hollowood~thornwall","traveller":"teodor","road_rec":"r543"},{"id":"e3015","day":81,"season":3,"sday":21,"kind":"road","imp":4,"text":"At season's end Marigold gives Fenwick the recipe, written in a spidery hand, with the secret ingredient crossed out and 'a friend' written beside it.","heroes":["h17","h13"],"parties":["p5"],"road":"hollowood~thornwall","traveller":"marigold","road_rec":"r546"},{"id":"e3060","day":82,"season":3,"sday":22,"kind":"party_life","imp":1,"text":"Fenwick suggests selling the cushions out of the carriage. Nobody answers.","heroes":["h17"],"parties":["p5"],"loc":"hollowood"},{"id":"e3080","day":82,"season":3,"sday":22,"kind":"talent","imp":2,"text":"A Thornwall child asks Bramble for the biggest thing she ever beat. It takes both arms to show. Chalk it up to Bane of Bosses.","heroes":["h13"],"parties":["p5"],"loc":"thornwall","skill":"bane_of_bosses","wx":"fog"},{"id":"e3105","day":83,"season":3,"sday":23,"kind":"road","imp":4,"text":"It is market day, and Old Maudie sells nothing, because every buyer is told that the cows are family. Bramble gets a rare smile for helping hold the herd.","heroes":["h13","h17"],"parties":["p5"],"road":"ironhaven~thornwall","traveller":"maudie","road_rec":"r558"},{"id":"e3134","day":83,"season":3,"sday":23,"kind":"talent","imp":1,"text":"Bramble spins her blade at a rest stop to loosen up. Two passing farmers stop to watch.","heroes":["h13"],"parties":["p5"],"loc":"thornwall","skill":"sword_dancer","wx":"fog"},{"id":"e3157","day":84,"season":3,"sday":24,"kind":"night_game","imp":2,"text":"The bandit blocks the way on the road to Ironhaven with a weapon in one hand and a request in the other: one game of Crooked Cards, and nobody gets hurt. A groan from the bandit, a grin from the crew, and Bandit's Marked Card changes hands, to be kept. Bramble wonders aloud what the bandit will do with the goods. Nobody wants the answer.","heroes":["h17","h13"],"parties":["p5"],"loc":"ironhaven","night":"n177","monster_game":"bandit"},{"id":"e3219","day":86,"season":3,"sday":26,"kind":"fight","imp":2,"text":"It's 2 Cave Trolls against the Green Arrows in Redcrag Hills, and it isn't close. Bramble ended it the plain way: Feint, and the cave troll on the ground. Loot: 30 silver each, 2 troll hide, 7 ore.","heroes":["h17","h13"],"parties":["p5"],"loc":"redcrag","fight":"f243","foes":["cave_troll","cave_troll"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"foe","reworded":-14},{"id":"e3220","day":86,"season":3,"sday":26,"kind":"talent","imp":2,"text":"Fenwick sorts trap parts on a blanket by size, then by age, then by how much he likes them.","heroes":["h17"],"parties":["p5"],"loc":"redcrag","skill":"professional_courtesy"},{"id":"e3260","day":87,"season":3,"sday":27,"kind":"fight","imp":2,"text":"With Bramble taking the worst of it, the Green Arrows see off a Cave Troll and a Giant Bat in Redcrag Hills. One Second Intention from Bramble and two of them were on the ground. Loot: 15 silver each, 1 troll hide, 2 troll haunches.","heroes":["h17","h13"],"parties":["p5"],"loc":"redcrag","fight":"f246","foes":["cave_troll","giant_bat"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"hero","reworded":-37},{"id":"e3263","day":87,"season":3,"sday":27,"kind":"fight","imp":3,"text":"In Redcrag Hills again, for the third time in two days: the Green Arrows defeat a Cave Troll and a Kobold. Two fights at once: the cave troll and the kobolds were already at each other's throats when The Green Arrows walked into the middle of it. Fenwick's Trip Wire took the strength out of the cave troll. Loot: 13 silver each, 1 troll hide, 1 ore.","heroes":["h17","h13"],"parties":["p5"],"loc":"redcrag","fight":"f247","foes":["cave_troll","kobold"],"where":"in Redcrag Hills","won":true,"close":false,"shape":"again","reworded":-39},{"id":"e3300","day":88,"season":3,"sday":28,"kind":"fight","imp":2,"text":"The Green Arrows meet 2 Drakes and a Giant Bat in Redcrag Hills and survive them. The kobolds came crashing in halfway through. After the drake, or after The Green Arrows, nobody is quite sure. Fenwick landed Volley on the giant bat hard enough to hear from the back. Ask the others what won it: Bramble's Inspire. Loot: 2 drake scales, 9 fangs & claws, 2 drake flanks.","heroes":["h17","h13"],"parties":["p5"],"loc":"redcrag","fight":"f255","foes":["drake","drake","giant_bat"],"where":"in Redcrag Hills","won":true,"close":true,"shape":"plain","reworded":-14},{"id":"e3312","day":88,"season":3,"sday":28,"kind":"talent","imp":1,"text":"Bramble sharpens her weapon all evening, humming the name of the next floor's boss. Bane of Bosses: one of the things Bramble learned the long way round.","heroes":["h13"],"parties":["p5"],"loc":"redcrag","skill":"bane_of_bosses"},{"id":"e3329","day":89,"season":3,"sday":29,"kind":"talent","imp":2,"text":"Fenwick draws a chain of snares on an Ironhaven table in spilt ale. The landlord asks for it again on paper. (One Snare Springs Another, if anyone's asking.)","heroes":["h17"],"parties":["p5"],"loc":"ironhaven","skill":"one_snare_springs_another"},{"id":"e3339","day":89,"season":3,"sday":29,"kind":"campfire","imp":1,"text":"Bramble fixes the squeak in Fenwick's lantern with a tiny screwdriver and a smug look.","heroes":["h13","h17"],"parties":["p5"],"loc":"ironhaven"},{"id":"e3355","day":90,"season":3,"sday":30,"kind":"party_life","imp":1,"text":"Fenwick says a cart is a cart, and a carriage is a cart with ideas.","heroes":["h17"],"parties":["p5"],"loc":"ironhaven"},{"id":"e3356","day":90,"season":3,"sday":30,"kind":"road","imp":4,"text":"Jory Bellwether cries Fenwick's deeds at a crossroads at the top of his voice, to nobody, and the echo carries them across the hills.","heroes":["h17","h13"],"parties":["p5"],"road":"ironhaven~thornwall","traveller":"jory","road_rec":"r611"}],"roles":{"h13":"Blade","h17":"Leader · Healer"},"quest":{"what":"Head home","where":"Thornwall","why":"heading home to Thornwall","floor":null,"floors":null},"tactics":{"front":["h13"],"back":["h17"],"plan":"Bramble holds the front; Fenwick picks off whatever gets close; Fenwick keeps everyone standing.","traits":{"boldness":0.38,"risk":0.29,"greed":-0.1,"sociability":0.17,"honor":0.26,"curiosity":-0.07,"temper":0.08,"loyalty":-0.24},"mix":"2 bows","notes":[],"style":["bold","skirmishers"],"skills":[{"label":"Damage","skills":[{"hero":"h13","id":"feint","name":"Feint","desc":"Look over there.","tags":["stealth","crit"],"rank":2,"uses":24},{"hero":"h13","id":"disarm","name":"Disarm","desc":"A twist of the wrist and their sword is on the floor.","tags":["crit"],"rank":3,"uses":21},{"hero":"h13","id":"dashing_strike","name":"Dashing Strike","desc":"Swings in on a chandelier, somehow, even outdoors.","tags":["crit"],"rank":2,"uses":7},{"hero":"h17","id":"volley","name":"Volley","desc":"Arrows like rain.","tags":[],"rank":1,"uses":2}]},{"label":"Healing","skills":[{"hero":"h17","id":"first_aid","name":"First Aid","desc":"Knows which end of a bandage goes where.","tags":["heal"],"rank":2,"uses":12},{"hero":"h17","id":"field_dressing","name":"Field Dressing","desc":"Moss, spit and a clean-ish rag.","tags":["heal"],"rank":3,"uses":9}]},{"label":"Defence","skills":[{"hero":"h13","id":"inspire","name":"Inspire","desc":"A verse about how great they all are. Bruises feel smaller.","tags":["command"],"rank":1,"uses":41},{"hero":"h13","id":"battle_cry","name":"Battle Cry","desc":"Bellows something inspiring and mostly vowels. Everyone swings harder.","tags":["command","rage"],"rank":2,"uses":37}]},{"label":"Tricks","skills":[{"hero":"h17","id":"trip_wire","name":"Trip Wire","desc":"Strung across the path before anyone noticed.","tags":["craft","stealth"],"rank":3,"uses":33},{"hero":"h13","id":"second_intention","name":"Second Intention","desc":"Planned the second cut before the first one landed.","tags":["crit"],"rank":2,"uses":18},{"hero":"h17","id":"snare_field","name":"Snare Field","desc":"Half the enemy finds the snares. The other half finds out.","tags":["nature","craft"],"rank":1,"uses":9},{"hero":"h13","id":"bane_of_bosses","name":"Bane of Bosses","desc":"The bigger the crown, the louder it falls.","tags":[],"rank":1,"uses":2},{"hero":"h17","id":"one_snare_springs_another","name":"One Snare Springs Another","desc":"Lays the snares in a chain. Every body that falls pulls the next one tight.","tags":[],"rank":1,"uses":1},{"hero":"h13","id":"better_odds","name":"The Odds Are Better","desc":"Three of you? Finally, a fair fight.","tags":[],"rank":1,"uses":1},{"hero":"h17","id":"camouflage","name":"Camouflage","desc":"Becomes a bush. A suspicious bush.","tags":["stealth","nature"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h17","id":"honed_edge","name":"Honed Edge","desc":"Sharpened every night, without fail.","tags":["craft"],"rank":1,"uses":0},{"hero":"h13","id":"precision","name":"Precision","desc":"Finds the gap every time.","tags":["crit"],"rank":3,"uses":0},{"hero":"h13","id":"steady_nerves","name":"Steady Nerves","desc":"Doesn't flinch. Neither does the party.","tags":["holy"],"rank":1,"uses":0},{"hero":"h13","id":"riposte","name":"Riposte","desc":"Every miss is an invitation.","tags":["crit"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h17","id":"trick_shot","name":"Trick Shot","desc":"Shoots the apple off your head. Asks first.","tags":["crit"],"rank":1,"uses":0},{"hero":"h17","id":"calligrapher","name":"Calligraphy","desc":"Beautiful letters. Even on shopping lists.","tags":["craft","lore"],"rank":2,"uses":0},{"hero":"h17","id":"smith_hands","name":"Smith's Hands","desc":"Fixes and upgrades their own gear.","tags":["craft"],"rank":1,"uses":0},{"hero":"h17","id":"trapfinder","name":"Trapfinder","desc":"Steps around the flagstone everyone else steps on.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h17","id":"bone_setting","name":"Bone Setting","desc":"Pull, twist, click. Better.","tags":["heal"],"rank":1,"uses":0},{"hero":"h17","id":"forager","name":"Forager","desc":"Finds dinner and herbs on any trail.","tags":["nature"],"rank":1,"uses":0},{"hero":"h17","id":"poultices","name":"Poultices","desc":"Mashes leaves. Wounds close.","tags":["heal","nature"],"rank":1,"uses":0},{"hero":"h13","id":"sword_dancer","name":"Sword Dancer","desc":"Dances with steel. Still has all ten toes.","tags":["crit","music"],"rank":1,"uses":0},{"hero":"h13","id":"brewer","name":"Brewer","desc":"Every camp has a bubbling pot that isn't soup.","tags":[],"rank":1,"uses":0},{"hero":"h13","id":"peacemaker","name":"Peacemaker","desc":"Stops the argument before it gets to the swords.","tags":["command","holy"],"rank":1,"uses":0}]}],"share":[{"hero":"h17","dmg":1086,"healed":221,"taken":0,"kills":6,"row":"back"},{"hero":"h13","dmg":2048,"healed":40,"taken":632,"kills":9,"row":"front"}],"ground":{"name":"The Ashveil Crypts","fights":9}},"trophies":[{"boss":"Gruk the Warchief","monster":"goblin_warchief","place":"Goblin Camp","day":5,"season":1,"fight":"f15"},{"boss":"The Mimic King","monster":"mimic_king","place":"Cragtooth Warren","day":15,"season":1,"fight":"f47"},{"boss":"Vessimir the Unburied","monster":"necromancer","place":"The Ashveil Crypts","day":25,"season":1,"fight":"f82"}]};